import { Treemap } from '@dreadnought/ui/react';
const data = { id: 'all', label: 'Бюджет', children: [{ id: 'team', label: 'Команда', children: [{ id: 'web', label: 'Web', value: 60 }, { id: 'api', label: 'API', value: 40 }] }] };
export function Example() { return <Treemap label="Бюджет команды" data={data} />; }

import { Treemap, useTreemap } from '@dreadnought/ui/react';
const data = {id:'all',label:'Все',children:[{id:'a',label:'Проект A',value:60},{id:'b',label:'Проект B',value:40}]};
function Controls() { const {page} = useTreemap(); return <button disabled={page.page === page.count} onClick={() => page.change(page.page + 1)}>Следующая страница</button>; }
export function Example() { return <Treemap label="Распределение" data={data} pageSize={1}><Controls /><Treemap.Breadcrumb /><Treemap.Location /><Treemap.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</Treemap.Plot><Treemap.Table /><Treemap.Pagination /><Treemap.Empty /></Treemap>; }
